INSERT INTO public.protocols VALUES ('6819e346-12b1-4239-a521-b580871ab515', NULL, 'Pre-Flight Safety Checklist', 'FAA Part 107-compliant pre-flight inspection for all drone operations. Must be completed before any flight activity.', 'pre_flight', 'all', '[{"id": "pf_01", "type": "check", "order": 1, "title": "Airspace Authorization", "required": true, "description": "Verify LAANC authorization or Part 107 waiver is active for this location. Check AirMap, Aloft, or FAA DroneZone for NOTAMs and TFRs."}, {"id": "pf_02", "type": "check", "order": 2, "title": "Weather Assessment", "required": true, "description": "Check winds below 25 mph, visibility > 3 statute miles, no precipitation, cloud ceiling > 500 ft above max flight altitude. Document conditions."}, {"id": "pf_03", "type": "check", "order": 3, "title": "Site Survey & Hazard ID", "required": true, "description": "Walk the launch/landing zone. Identify overhead wires, trees, structures, people, animals, and RF interference sources within 400 ft."}, {"id": "pf_04", "type": "check", "order": 4, "title": "Aircraft Physical Inspection", "required": true, "description": "Inspect all propellers for cracks, chips, or deformation. Check motor mounts, landing gear, and fuselage for damage. Verify all screws are tight."}, {"id": "pf_05", "type": "check", "order": 5, "title": "Battery Status", "required": true, "description": "Confirm flight batteries are charged ≥ 90%. Check for swelling, damage, or abnormal heat. Verify battery firmware is current."}, {"id": "pf_06", "type": "check", "order": 6, "title": "Payload & Sensor Check", "required": true, "description": "Confirm camera/sensor is mounted securely. Check lens for obstructions. Verify gimbal moves freely across full range. Test video feed."}, {"id": "pf_07", "type": "check", "order": 7, "title": "Remote Controller Check", "required": true, "description": "RC battery > 80%. Signal linked. Control surfaces responding correctly. Return-to-Home altitude set (minimum 100 ft above tallest obstacle)."}, {"id": "pf_08", "type": "check", "order": 8, "title": "Storage Media", "required": true, "description": "Confirm SD/SSD card is inserted, formatted, and has sufficient capacity for the mission. Verify no previous mission data unless intentional."}, {"id": "pf_09", "type": "check", "order": 9, "title": "GPS & Compass Calibration", "required": true, "description": "Verify GPS lock ≥ 10 satellites. Check for compass interference warnings. Calibrate if relocating by > 50 miles from last calibration."}, {"id": "pf_10", "type": "check", "order": 10, "title": "Mission Parameters Review", "required": true, "description": "Review and confirm flight altitude, speed, overlap settings, and KML/mission plan loaded into GCS app. Verify geofence boundaries."}, {"id": "pf_11", "type": "check", "order": 11, "title": "Emergency Procedure Brief", "required": true, "description": "Identify nearest hospital/emergency services. Confirm abort plan, emergency landing zones, and lost-link procedures with any crew members."}, {"id": "pf_12", "type": "sign", "order": 12, "title": "Pilot Certification", "required": true, "description": "Confirm current FAA Remote Pilot Certificate is in possession. Verify medical self-certification (not impaired by fatigue, medication, or illness)."}]', '2.1', true, true, NULL, '2026-03-26 15:58:08.192965-04', '2026-03-26 15:58:08.192965-04');
INSERT INTO public.protocols VALUES ('aa8e73d8-59dc-4b25-b0a6-e12da41b2f3f', NULL, 'Solar Farm Inspection Protocol', 'Standard operating procedure for thermal and RGB drone inspection of utility-scale solar installations. Aligned with IEC 62446-3 and ASTM E1934 standards.', 'mission', 'solar', '[{"id": "s_01", "type": "input", "order": 1, "title": "Irradiance Verification", "required": true, "description": "Confirm solar irradiance ≥ 600 W/m² for thermal anomaly detection. Below this threshold thermal contrast is insufficient for reliable fault mapping. Document GHI reading at mission start."}, {"id": "s_02", "type": "check", "order": 2, "title": "Thermal Camera Warm-Up", "required": true, "description": "Allow thermal sensor to reach operating temperature for minimum 10 minutes before data collection begins (FLIR-type sensors require stabilization)."}, {"id": "s_03", "type": "input", "order": 3, "title": "Reference Panel Baseline", "required": false, "description": "Capture thermal baseline of known-good reference panel before scan. Record temperature reading for calibration comparison during analysis."}, {"id": "s_04", "type": "check", "order": 4, "title": "Flight Grid Confirmation", "required": true, "description": "Verify flight grid covers 100% of panel array with ≥ 20% frontal overlap and ≥ 60% side overlap. Altitude set for ≥ 5 cm/pixel GSD on thermal."}, {"id": "s_05", "type": "check", "order": 5, "title": "Row & Block Marking", "required": true, "description": "Confirm row/block numbering matches site layout diagram provided by client. Document any discrepancies for the final report."}, {"id": "s_06", "type": "check", "order": 6, "title": "Wind & Shade Check", "required": true, "description": "Pause or abort if wind > 15 mph at flight altitude (creates panel vibration artifacts). Avoid imaging panels in shadow — reschedule those sections."}, {"id": "s_07", "type": "check", "order": 7, "title": "Anomaly Tagging Protocol", "required": false, "description": "During live review, tag any thermal anomaly with GPS coordinates in GCS. Categories: Cell fault, String fault, Module bypass, Soiling, Delamination, Hot spot."}, {"id": "s_08", "type": "check", "order": 8, "title": "RGB Orthomosaic Pass", "required": false, "description": "After thermal, fly a secondary RGB pass for physical damage documentation (cracked glass, bird droppings, delamination, shade objects)."}, {"id": "s_09", "type": "check", "order": 9, "title": "Data Integrity Check", "required": true, "description": "Before leaving site, review captured files — verify no missing rows, confirm frame count matches expected coverage, spot-check GPS embedding."}, {"id": "s_10", "type": "sign", "order": 10, "title": "Site Access & Safety Compliance", "required": true, "description": "Confirm coordination with site energy manager. Maintain safe distance from inverters (10 ft minimum) and substations. Follow site-specific arc flash protocols."}]', '3.0', true, false, NULL, '2026-03-26 15:58:08.207988-04', '2026-03-26 15:58:08.207988-04');
INSERT INTO public.protocols VALUES ('2528a60c-9484-49b0-9af5-a7c8b28fca43', NULL, 'Insurance Property Inspection Protocol', 'Rooftop and property inspection procedure for P&C insurance underwriting and claims. Aligned with carrier SLAs and NAIC guidelines.', 'mission', 'insurance', '[{"id": "i_01", "type": "sign", "order": 1, "title": "Client Authorization", "required": true, "description": "Confirm written authorization from property owner or insurer. Verify inspection address matches claim/policy number. Do not fly adjacent properties without separate authorization."}, {"id": "i_02", "type": "check", "order": 2, "title": "Property Survey", "required": true, "description": "Identify all structures on parcel: main structure, detached garage, outbuildings, pools, fencing. Capture establishing shot showing full property boundary."}, {"id": "i_03", "type": "check", "order": 3, "title": "Roof Condition Documentation", "required": true, "description": "Capture all four roof facets at 45° and nadir angles. Document: ridge, valleys, flashings, penetrations, gutters, downspouts, chimney, skylights, HVAC equipment."}, {"id": "i_04", "type": "input", "order": 4, "title": "Damage Category Assessment", "required": true, "description": "Identify and photograph any visible damage: hail impact marks, wind-lifted shingles, missing materials, debris impact, ice damming, moss/algae growth, structural sagging."}, {"id": "i_05", "type": "check", "order": 5, "title": "Measurement Documentation", "required": false, "description": "Capture reference objects for scale (HVAC units, standard shingles). Flag slope areas requiring pitch measurement. Ensure sufficient data for Hover/EagleView comparison."}, {"id": "i_06", "type": "check", "order": 6, "title": "Elevation & Exterior", "required": true, "description": "Document all four building elevations, siding condition, window integrity, foundation visible areas, and any fire or water intrusion evidence."}, {"id": "i_07", "type": "check", "order": 7, "title": "Proximity Rules", "required": true, "description": "Maintain minimum 25 ft from structures during flight. Do not fly below eave line of neighboring structures. Respect 400 ft altitude ceiling."}, {"id": "i_08", "type": "sign", "order": 8, "title": "Privacy Compliance", "required": true, "description": "Do not capture interior of any structure through windows. Do not linger over neighboring properties. Disable any live streaming to external services."}, {"id": "i_09", "type": "check", "order": 9, "title": "Image Quality Verification", "required": true, "description": "Confirm minimum resolution of 12MP per image. All images must be GPS-tagged. Verify no motion blur, overexposure, or obstruction. Minimum 50 images for standard residential."}]', '2.2', true, false, NULL, '2026-03-26 15:58:08.228373-04', '2026-03-26 15:58:08.228373-04');
INSERT INTO public.protocols VALUES ('7e4d227d-8252-43ba-a514-7f947f4b5d6a', NULL, 'Utility Infrastructure Inspection Protocol', 'Inspection protocol for power transmission lines, distribution networks, substations, and related infrastructure. Aligned with NERC FAC-001 and OSHA 1910.269.', 'mission', 'utilities', '[{"id": "u_01", "type": "sign", "order": 1, "title": "Utility Coordination", "required": true, "description": "Confirm inspection clearance with utility operations center. Get work order number and confirm outage status if applicable. Emergency contact number on file."}, {"id": "u_02", "type": "check", "order": 2, "title": "Power Line Clearances", "required": true, "description": "Confirm minimum safe separation: 50 ft horizontal from energized HV lines, 10 ft from low-voltage distribution. Electric field may interfere with compass — recalibrate after positioning."}, {"id": "u_03", "type": "check", "order": 3, "title": "EMF Interference Test", "required": true, "description": "Power on aircraft at inspection start point. Verify no compass or IMU errors. If errors present, move launch point 100+ ft from nearest conductor."}, {"id": "u_04", "type": "check", "order": 4, "title": "Transmission Structure Inspection", "required": true, "description": "Inspect: insulator strings, conductor clamps, vibration dampers, tower/pole hardware, ground wire, arc marks, wildlife nesting, vegetation encroachment."}, {"id": "u_05", "type": "input", "order": 5, "title": "Thermal Scan for Hot Connections", "required": false, "description": "Use thermal camera to detect overheating: splice joints, dead-end clamps, insulator failures, transformer connections. Flag any ΔT > 15°C above ambient."}, {"id": "u_06", "type": "check", "order": 6, "title": "LiDAR Vegetation Clearance", "required": false, "description": "If LiDAR-equipped: verify required clearance between conductors and vegetation per applicable NERC FAC-003 standards. Flag vegetation within encroachment zone."}, {"id": "u_07", "type": "check", "order": 7, "title": "Emergency Landing Plan", "required": true, "description": "Identify emergency landing zones that are clear of power lines and structures for each segment. Do not fly directly over energized equipment."}, {"id": "u_08", "type": "check", "order": 8, "title": "ROW Documentation", "required": false, "description": "Photograph all signage, access roads, fencing conditions, and right-of-way encroachments along patrol corridor. Note GPS coordinates of access points."}]', '2.0', true, false, NULL, '2026-03-26 15:58:08.230092-04', '2026-03-26 15:58:08.230092-04');
INSERT INTO public.protocols VALUES ('c9ac1afa-4b30-4187-ba71-f0f55c23fc03', NULL, 'Telecommunications Tower Inspection Protocol', 'Close-proximity drone inspection of cell towers, broadcast antennas, and related telecom infrastructure. Aligned with NATE TCIA and TIA-222 standards.', 'mission', 'telecom', '[{"id": "t_01", "type": "sign", "order": 1, "title": "RF Emissions Clearance", "required": true, "description": "Confirm active antenna emissions status with tower manager. If radiating: use RF-shielded aircraft or RF monitoring equipment. Do not fly within 10 ft of active antenna face."}, {"id": "t_02", "type": "check", "order": 2, "title": "FAA Marking Verification", "required": true, "description": "Confirm tower height and FAA obstruction lighting per AC 70/7460-1. Structures > 200 AGL require special operations planning or waiver."}, {"id": "t_03", "type": "check", "order": 3, "title": "Tower Structure Inspection", "required": true, "description": "Inspect: base section, anchor bolts, climbing pegs, guy wire attachments, weathering/corrosion on structural members, welds, and coatings."}, {"id": "t_04", "type": "check", "order": 4, "title": "Antenna & Line System", "required": true, "description": "Document all antenna mounting brackets, cable management, weatherproofing boots, RET actuators, and line pressurization fittings. Note any cable kinking or UV degradation."}, {"id": "t_05", "type": "check", "order": 5, "title": "Close-Proximity Flight Limits", "required": true, "description": "Maximum flight speed 2 m/s within 20 ft of structure. Altitude change not to exceed 1 m/s vertical. Manual flight mode required within 10 ft of structure."}, {"id": "t_06", "type": "check", "order": 6, "title": "GPS Denied Operations", "required": true, "description": "Confirm pilot is qualified for non-GPS visual positioning. Test ATTI/manual mode before approaching tower (GPS shadow expected near structure)."}, {"id": "t_07", "type": "input", "order": 7, "title": "Equipment Log", "required": false, "description": "Record all attached equipment makes/models, their mounting heights, azimuth direction, and visible condition rating (1-5 scale)."}]', '1.8', true, false, NULL, '2026-03-26 15:58:08.232501-04', '2026-03-26 15:58:08.232501-04');
INSERT INTO public.protocols VALUES ('d903a041-f208-401d-8920-c5be7eb7884a', NULL, 'Construction Site Progress Inspection Protocol', 'Site progress monitoring and documentation protocol for active construction projects. Aligned with OSHA 1926 construction safety standards.', 'mission', 'construction', '[{"id": "c_01", "type": "sign", "order": 1, "title": "Site Safety Briefing", "required": true, "description": "Check in with site safety manager. Receive active hazard briefing: crane swing zones, personnel exclusion areas, scheduled concrete pours, delivery windows."}, {"id": "c_02", "type": "check", "order": 2, "title": "Hard Hat & Vest", "required": true, "description": "Pilot and any ground crew must wear hard hat and high-visibility vest at all times on active construction site."}, {"id": "c_03", "type": "check", "order": 3, "title": "Crane & Heavy Equipment Coordination", "required": true, "description": "Notify crane operator and all heavy equipment operators before flight. Establish radio channel. Cease flight if crane swings into flight path."}, {"id": "c_04", "type": "check", "order": 4, "title": "People Clearance Zone", "required": true, "description": "Establish minimum 25 ft exclusion zone under flight path. Brief all workers. Post spotter on boundaries if area cannot be cleared."}, {"id": "c_05", "type": "check", "order": 5, "title": "Progress Documentation Coverage", "required": true, "description": "Capture full site perimeter at nadir and oblique. Photograph: foundation/slab work, structural steel/framing progress, MEP rough-in visible, exterior cladding, site logistics."}, {"id": "c_06", "type": "check", "order": 6, "title": "GCP / Survey Accuracy", "required": false, "description": "If photogrammetry deliverable required: verify GCPs are placed and surveyed. Capture each GCP at minimum 5 viewpoints while maintaining safe clearance."}, {"id": "c_07", "type": "check", "order": 7, "title": "Dust & Debris Risk", "required": true, "description": "Avoid flying directly over active concrete cutting, grinding, or demolition operations. Dust infiltration can damage sensors and motors."}]', '1.5', true, false, NULL, '2026-03-26 15:58:08.239707-04', '2026-03-26 15:58:08.239707-04');
INSERT INTO public.protocols VALUES ('bd520fbe-867e-474d-89e2-3c992cbd7757', NULL, 'Post-Flight Wrap & Data Handoff Protocol', 'Standard post-flight inspection, data verification, and equipment storage procedures. Required after every flight operation.', 'post_flight', 'all', '[{"id": "post_01", "type": "check", "order": 1, "title": "Aircraft Inspection", "required": true, "description": "Inspect all propellers for damage sustained during flight. Check motor temps (should cool < 45°C within 5 min). Inspect fuselage for new damage. Check landing gear."}, {"id": "post_02", "type": "check", "order": 2, "title": "Battery Care", "required": true, "description": "Allow batteries to cool before storage (≥ 15 min post-flight). Discharge to storage level (50-60%) if not flying within 24 hours. Log cycle count."}, {"id": "post_03", "type": "check", "order": 3, "title": "Data Offload & Verification", "required": true, "description": "Offload all media to at least 2 separate storage devices (primary + backup). Verify file count matches expected frame count. Confirm GPS data is embedded in EXIF."}, {"id": "post_04", "type": "check", "order": 4, "title": "Data Quality Review", "required": true, "description": "Spot-check 10% of captured images/thermal frames for focus, exposure, coverage gaps, and GPS accuracy drift. Flag any anomalies before leaving site."}, {"id": "post_05", "type": "input", "order": 5, "title": "Flight Log Entry", "required": true, "description": "Record in flight log: date, location, pilot name, aircraft tail number, battery cycles used, flight durations, max altitude, and any incidents."}, {"id": "post_06", "type": "check", "order": 6, "title": "Incident / Anomaly Report", "required": true, "description": "If any near-miss, fly-away, equipment malfunction, or property contact occurred — complete incident report immediately before leaving site."}, {"id": "post_07", "type": "check", "order": 7, "title": "Equipment Storage", "required": true, "description": "Clean aircraft and sensors. Store batteries in LiPo-safe bag. Secure all equipment in transport cases. Confirm no equipment left at site."}, {"id": "post_08", "type": "sign", "order": 8, "title": "Client Site Restoration", "required": true, "description": "Return any moved objects to original position. Ensure gates/access points are secured as found. Report completed to site contact or operations center."}]', '2.0', true, true, NULL, '2026-03-26 15:58:08.24178-04', '2026-03-26 15:58:08.24178-04');
INSERT INTO public.protocols VALUES ('073cda71-b5da-4d4f-b201-774f47058d2d', NULL, 'Emergency Procedures & Lost Aircraft Protocol', 'Immediate action procedures for aircraft emergencies, loss of control link, fly-away events, and injury response. Review before every operation.', 'emergency', 'all', '[{"id": "e_01", "type": "check", "order": 1, "title": "Loss of Control Link", "required": true, "description": "Aircraft should execute RTH automatically. Monitor countdown. If aircraft does not return: note last known GPS coordinates, alert all personnel to clear area, contact ATC if near controlled airspace."}, {"id": "e_02", "type": "check", "order": 2, "title": "Fly-Away Response", "required": true, "description": "Immediately alert all ground crew to hazard. Call 911 if aircraft continues beyond visual range. Note last GPS position from GCS. File FAA incident report within 10 days per Part 107.9."}, {"id": "e_03", "type": "check", "order": 3, "title": "Motor or Propeller Failure", "required": true, "description": "Attempt controlled descent to safest available area. Cut throttle before impact if over people. Do not reach into spinning motors. Alert personnel to impact zone."}, {"id": "e_04", "type": "check", "order": 4, "title": "Battery Fire Response", "required": true, "description": "Do NOT use water on LiPo fire. Use dry sand or ABC extinguisher. Move aircraft away from fuel/combustibles if safe to do so. Call 911. Do not inhale fumes."}, {"id": "e_05", "type": "check", "order": 5, "title": "Injury Response", "required": true, "description": "Call 911 immediately for any person injured. Administer first aid if certified. Do not move injured person unless in immediate danger. Preserve scene for investigation."}, {"id": "e_06", "type": "sign", "order": 6, "title": "FAA Incident Reporting", "required": true, "description": "Reportable events: serious injury, loss of consciousness, property damage > $500. File ASRS report if applicable. Contact company safety officer within 1 hour of incident."}, {"id": "e_07", "type": "input", "order": 7, "title": "Emergency Contacts On File", "required": true, "description": "Confirm you have noted: nearest hospital address, site emergency contact, company operations number, local ATC frequency, and FAA FSDO contact."}]', '1.3', true, false, NULL, '2026-03-26 15:58:08.243613-04', '2026-03-26 15:58:08.243613-04');
INSERT INTO public.protocols VALUES ('1cc0c6c3-0440-4f3d-9cf5-417cee22b913', NULL, 'Post-Flight & Data Securment', 'Required procedures upon landing to ensure data integrity and UAS safety.', 'post_flight', 'all', '[{"id": "po1", "type": "check", "order": 1, "title": "Power Down Sequence", "required": true, "description": "Power down the aircraft first, then the remote controller."}, {"id": "po2", "type": "check", "order": 2, "title": "Data Verification", "required": true, "description": "Review the SD card to ensure images were successfully captured and are not corrupt."}, {"id": "po3", "type": "check", "order": 3, "title": "Post-Flight Airframe Check", "required": true, "description": "Inspect for any damage that occurred during flight (bird strikes, dust ingress)."}, {"id": "po4", "type": "sign", "order": 4, "title": "Pilot Signature", "required": true, "description": "Sign to confirm the mission was completed without incident."}]', '1.0', true, true, NULL, '2026-05-04 22:10:53.366563-04', '2026-05-04 22:10:53.366563-04');
INSERT INTO public.protocols VALUES ('5a50980a-669a-4ead-ab28-c800821ec0b0', NULL, 'Emergency Flyaway / Loss of Link Protocol', 'Immediate actions to take if the remote controller loses connection with the aircraft.', 'emergency', 'all', '[{"id": "em1", "type": "check", "order": 1, "title": "Attempt Reconnection", "required": true, "description": "Adjust antenna orientation and move to higher ground if possible to regain line-of-sight."}, {"id": "em2", "type": "check", "order": 2, "title": "Monitor RTH", "required": true, "description": "Listen for the aircraft initiating its Return-To-Home sequence."}, {"id": "em3", "type": "input", "order": 3, "title": "Airspace Advisory", "required": false, "description": "If the drone flies away into controlled airspace, immediately contact the local ATC facility."}]', '1.0', true, false, NULL, '2026-05-04 22:10:53.370263-04', '2026-05-04 22:10:53.370263-04');
INSERT INTO public.protocols VALUES ('fbf3cb78-4c99-46d0-a3a9-79a64e0f7317', NULL, 'Aircraft Firmware & Software Pre-Mission Check', 'Ensures aircraft, controller, and GCS software are fully updated and compatible before departure to the field. Prevents software-related failures in the field.', 'pre_flight', 'all', '[{"id": "fw_01", "type": "check", "order": 1, "title": "Aircraft Firmware Version", "required": true, "description": "Check aircraft firmware against manufacturer latest release. Do not update firmware in the field — complete updates at office with stable power."}, {"id": "fw_02", "type": "check", "order": 2, "title": "Remote Controller Firmware", "required": true, "description": "Verify RC firmware version matches aircraft compatibility matrix. Mismatched firmware can cause unpredictable behavior."}, {"id": "fw_03", "type": "check", "order": 3, "title": "GCS App Version", "required": true, "description": "Confirm ground control station app (DJI Pilot, DroneDeploy, Pix4D Capture, etc.) is on approved version. Check for critical bug notices."}, {"id": "fw_04", "type": "check", "order": 4, "title": "Mission File Compatibility", "required": true, "description": "Open and verify the mission file (.kml, .kmz, .waypoint) loads correctly in GCS with no error flags before departure."}, {"id": "fw_05", "type": "check", "order": 5, "title": "Offline Maps Downloaded", "required": false, "description": "If remote area: confirm offline map tiles covering the mission area are downloaded. Do not rely on cellular connectivity in the field."}, {"id": "fw_06", "type": "check", "order": 6, "title": "Return-to-Home Settings", "required": true, "description": "Set RTH altitude ≥ 120 ft above launch or highest obstacle. Confirm low battery RTH threshold (typically 20%). Confirm signal loss action = RTH."}]', '1.2', true, false, NULL, '2026-03-27 19:46:40.206622-04', '2026-03-27 19:46:40.206622-04');
INSERT INTO public.protocols VALUES ('af15fbd8-a54d-4357-a3e4-1dba42e3b741', NULL, 'Multi-Crew / Observer Briefing Protocol', 'Required when operating with a visual observer or additional crew. Establishes communication, roles, and responsibility assignments.', 'pre_flight', 'all', '[{"id": "mc_01", "type": "check", "order": 1, "title": "Role Assignment", "required": true, "description": "Designate: Pilot in Command (PIC), Visual Observer (VO), Mission Commander (if different from PIC). Only one person is PIC at any time."}, {"id": "mc_02", "type": "check", "order": 2, "title": "Communication Protocol", "required": true, "description": "Establish voice communication method (radios, verbal call-outs). Agree on standardized call-outs: \"Traffic!\", \"Hold!\", \"RTH!\", \"Land now!\""}, {"id": "mc_03", "type": "check", "order": 3, "title": "Visual Observer Positioning", "required": false, "description": "VO should be positioned for maximum airspace visibility different from PIC position. Establish VO abort authority and call-out procedure."}, {"id": "mc_04", "type": "check", "order": 4, "title": "Emergency Action Review", "required": true, "description": "Brief all crew on emergency action procedures: who calls 911, who manages crowd control, who handles fire suppression equipment."}, {"id": "mc_05", "type": "sign", "order": 5, "title": "Crew Acknowledgment", "required": true, "description": "All crew members confirm they understand their roles and have no concerns before flight commences."}]', '1.0', true, false, NULL, '2026-03-27 19:46:40.227642-04', '2026-03-27 19:46:40.227642-04');
INSERT INTO public.protocols VALUES ('993ffe47-e869-49c7-8484-413cc0675564', NULL, 'Solar Farm Thermal Inspection Protocol', 'Standard operating procedure for thermal and RGB drone inspection of utility-scale solar installations. Aligned with IEC 62446-3 and ASTM E1934 standards.', 'mission', 'solar', '[{"id": "s_01", "type": "input", "order": 1, "title": "Irradiance Verification", "required": true, "description": "Confirm solar irradiance ≥ 600 W/m² for thermal anomaly detection. Document GHI reading at mission start."}, {"id": "s_02", "type": "check", "order": 2, "title": "Thermal Camera Warm-Up", "required": true, "description": "Allow thermal sensor to reach operating temperature for minimum 10 minutes. FLIR-type sensors require stabilization before data collection."}, {"id": "s_03", "type": "input", "order": 3, "title": "Reference Panel Baseline", "required": false, "description": "Capture thermal baseline of known-good reference panel. Record temperature for calibration comparison during analysis."}, {"id": "s_04", "type": "check", "order": 4, "title": "Flight Grid Confirmation", "required": true, "description": "Verify flight grid covers 100% of array with ≥ 20% frontal overlap and ≥ 60% side overlap. GSD ≥ 5 cm/pixel on thermal."}, {"id": "s_05", "type": "check", "order": 5, "title": "Row & Block Marking Verification", "required": true, "description": "Confirm row/block numbering matches site layout diagram. Document any discrepancies for the final report."}, {"id": "s_06", "type": "check", "order": 6, "title": "Wind & Shade Check", "required": true, "description": "Pause or abort if wind > 15 mph at flight altitude. Avoid imaging panels in shadow — reschedule those sections."}, {"id": "s_07", "type": "check", "order": 7, "title": "Anomaly Tagging", "required": false, "description": "Tag thermal anomalies with GPS coordinates. Categories: Cell fault, String fault, Module bypass, Soiling, Delamination, Hot spot, Diode failure."}, {"id": "s_08", "type": "check", "order": 8, "title": "RGB Orthomosaic Pass", "required": false, "description": "After thermal, fly secondary RGB pass for physical damage documentation (cracked glass, bird droppings, delamination, shade objects)."}, {"id": "s_09", "type": "check", "order": 9, "title": "Data Integrity Check", "required": true, "description": "Before leaving site: verify no missing rows, confirm frame count matches expected coverage, spot-check GPS embedding."}, {"id": "s_10", "type": "sign", "order": 10, "title": "Site Access Compliance", "required": true, "description": "Maintain safe distance from inverters (10 ft minimum) and substations. Follow site-specific arc flash and lockout/tagout protocols."}]', '3.0', true, false, NULL, '2026-03-27 19:46:40.229468-04', '2026-03-27 19:46:40.229468-04');
INSERT INTO public.protocols VALUES ('1084d199-032c-443e-a01d-3181c2f19823', NULL, 'Solar Fault Classification & Severity Rating', 'Standardized fault classification protocol for thermal solar inspections. Ensures consistent severity grading across all pilots and clients.', 'mission', 'solar', '[{"id": "sfc_01", "type": "check", "order": 1, "title": "Severity Scale Confirmation", "required": true, "description": "Use standard scale: Class 1 (ΔT < 5°C = Monitor), Class 2 (ΔT 5-15°C = Schedule repair), Class 3 (ΔT 15-40°C = Urgent), Class 4 (ΔT > 40°C = Immediate shutdown)."}, {"id": "sfc_02", "type": "input", "order": 2, "title": "Ambient Temperature Reference", "required": true, "description": "Record ambient air temperature at mission start and end. All ΔT calculations must be relative to ambient, not absolute panel temperature."}, {"id": "sfc_03", "type": "check", "order": 3, "title": "String vs Module Fault", "required": false, "description": "Classify string faults (affecting > 1 module in series) separately from single-module faults. Note string number in SCADA system if available."}, {"id": "sfc_04", "type": "check", "order": 4, "title": "Bypass Diode Fault Pattern", "required": false, "description": "Identify bypass diode failures (1/3 or 2/3 of module heated). Flag for immediate O&M as diode failures permanently reduce string output."}, {"id": "sfc_05", "type": "check", "order": 5, "title": "Soiling vs Thermal Fault", "required": true, "description": "Differentiate soiling (uniform, low-contrast patches) from genuine thermal faults. Soiling appears at uniform temperature elevation; faults show discrete hot spots."}, {"id": "sfc_06", "type": "input", "order": 6, "title": "Photo Evidence per Fault", "required": true, "description": "Capture both thermal and RGB photo of each Class 2+ fault. Note GPS coordinates, row number, module position, and severity class in field log."}]', '1.5', true, false, NULL, '2026-03-27 19:46:40.231149-04', '2026-03-27 19:46:40.231149-04');
INSERT INTO public.protocols VALUES ('927467ec-cf55-43ae-8296-e54dbea5e1b6', NULL, 'Hail Damage Assessment Protocol', 'Specialized roof inspection protocol for hail damage claims. Provides standardized methodology for identifying and documenting hail impact patterns.', 'mission', 'insurance', '[{"id": "hd_01", "type": "input", "order": 1, "title": "Storm Data Reference", "required": true, "description": "Note storm date, hail size reported (NWS or carrier data), and storm track direction. This provides context for expected impact density and pattern direction."}, {"id": "hd_02", "type": "input", "order": 2, "title": "Test Square Documentation", "required": true, "description": "Identify and photograph a 10x10 ft test square on each roof facet. Count visible impact marks per test square for density estimate."}, {"id": "hd_03", "type": "check", "order": 3, "title": "Spatter Marks vs True Impacts", "required": true, "description": "Distinguish hail impacts (bruising with granule loss, rounded depression) from UV weathering, foot traffic, or installation damage (sharp edges, no granule loss)."}, {"id": "hd_04", "type": "check", "order": 4, "title": "Ridge Cap & Hip Assessment", "required": true, "description": "Capture close-up of ridge cap — most visible location for hail damage pattern confirmation. Note impact spacing consistency with reported hail size."}, {"id": "hd_05", "type": "check", "order": 5, "title": "Soft Metal Documentation", "required": true, "description": "Photograph all soft metals: vents, flashing, gutters, downspouts, HVAC fins. Hail impacts clearly visible on soft metals confirm event."}, {"id": "hd_06", "type": "input", "order": 6, "title": "Pre-existing Damage Notation", "required": false, "description": "Flag any damage inconsistent with current storm event (weathering, moss, prior repairs, exposed decking). Document separately from storm-related damage."}]', '1.3', true, false, NULL, '2026-03-27 19:46:40.235412-04', '2026-03-27 19:46:40.235412-04');
INSERT INTO public.protocols VALUES ('f51e49fa-fc82-434a-af12-c5776823a1cd', NULL, 'Substation & Switching Equipment Inspection', 'Close-proximity inspection protocol for electrical substations, transformers, and switching equipment. High-hazard environment protocol.', 'mission', 'utilities', '[{"id": "sub_01", "type": "sign", "order": 1, "title": "Substation Access Authorization", "required": true, "description": "Obtain signed access authorization from utility operations manager. Confirm substation is in normal operating configuration. No switching operations during aerial inspection."}, {"id": "sub_02", "type": "input", "order": 2, "title": "Equipment Energization Status", "required": true, "description": "Confirm which buses, transformers, and breakers are energized vs de-energized prior to flight planning. Maintain 30 ft minimum from energized HV equipment."}, {"id": "sub_03", "type": "check", "order": 3, "title": "Ferrous Object Check", "required": true, "description": "Remove all ferrous metal objects from aircraft before entry (if near high-current equipment). Magnetic fields near busbars can cause compass anomalies."}, {"id": "sub_04", "type": "check", "order": 4, "title": "Transformer Inspection", "required": true, "description": "Document: oil level inspection port, cooling fins condition, bushings, surge arresters, pressure relief, corrosion on tank, and any oil staining below unit."}, {"id": "sub_05", "type": "input", "order": 5, "title": "Thermal Transformer Scan", "required": false, "description": "Image all transformer bushings and high-current connections with thermal camera. Flag any bushing with ΔT > 10°C compared to adjacent phases."}, {"id": "sub_06", "type": "check", "order": 6, "title": "Control Building & Fence", "required": false, "description": "Document control building exterior, grounding strap connections, security fencing integrity, and perimeter lighting. Note any unauthorized access indicators."}]', '1.1', true, false, NULL, '2026-03-27 19:46:40.239325-04', '2026-03-27 19:46:40.239325-04');
INSERT INTO public.protocols VALUES ('6eeca742-4f7a-4711-9adb-9ee08128fde4', NULL, 'Guy Wire & Anchor Inspection Protocol', 'Specialized inspection of guyed tower anchor systems, turnbuckles, and guy wire condition. Detects corrosion, broken strands, and anchor displacement.', 'mission', 'telecom', '[{"id": "gw_01", "type": "input", "order": 1, "title": "Guy Level Identification", "required": true, "description": "Identify all guy levels (e.g., 1/4, 1/2, 3/4 height) and number of guys per level. Confirm against tower specifications. Map any deviations."}, {"id": "gw_02", "type": "check", "order": 2, "title": "Anchor Point Inspection", "required": true, "description": "Photograph each anchor: concrete helix condition, bearing plate, anchor rod, and ground seal. Note cracking, settlement, or corrosion."}, {"id": "gw_03", "type": "check", "order": 3, "title": "Turnbuckle & Hardware", "required": true, "description": "Inspect turnbuckles, shackles, and thimbles at anchor and tower attachment. Check for corrosion, deformation, open clevis pins, and missing cotter pins."}, {"id": "gw_04", "type": "check", "order": 4, "title": "Wire Strand Condition", "required": true, "description": "Fly each guy wire from anchor to tower attachment. Identify broken strands (visible bright wires), uniform corrosion, and loose or missing preformed grip rods."}, {"id": "gw_05", "type": "input", "order": 5, "title": "Tension Assessment", "required": false, "description": "Document visible sag between attachment points. Significant visual sag (vs other guys at same level) may indicate incorrect tension — flag for field measurement."}]', '1.0', true, false, NULL, '2026-03-27 19:46:40.242107-04', '2026-03-27 19:46:40.242107-04');
INSERT INTO public.protocols VALUES ('b5da318d-7a9e-4487-b44b-805455029271', NULL, 'Construction Progress Monitoring Protocol', 'Site progress monitoring and documentation for active construction projects. Aligned with OSHA 1926 construction safety standards.', 'mission', 'construction', '[{"id": "c_01", "type": "sign", "order": 1, "title": "Site Safety Briefing", "required": true, "description": "Check in with site safety manager. Receive active hazard briefing: crane swing zones, exclusion areas, scheduled pours, delivery windows."}, {"id": "c_02", "type": "check", "order": 2, "title": "PPE Compliance", "required": true, "description": "Pilot and ground crew must wear hard hat, high-visibility vest, and steel-toed footwear at all times on active construction site."}, {"id": "c_03", "type": "check", "order": 3, "title": "Crane & Heavy Equipment Coordination", "required": true, "description": "Notify crane operator and all heavy equipment operators before flight. Establish radio channel (typically site net). Cease flight if crane swings into flight path."}, {"id": "c_04", "type": "check", "order": 4, "title": "Personnel Exclusion Zone", "required": true, "description": "Establish minimum 25 ft exclusion zone under flight path. Brief all workers. Post spotter on boundaries if area cannot be cleared."}, {"id": "c_05", "type": "check", "order": 5, "title": "Progress Coverage Checklist", "required": true, "description": "Capture: full site perimeter, foundation/slab work, structural steel/framing progress, MEP rough-in, exterior cladding, site logistics, and finished areas."}, {"id": "c_06", "type": "check", "order": 6, "title": "GCP Photogrammetry Setup", "required": false, "description": "If photogrammetry deliverable required: verify GCPs are placed and surveyed. Capture each GCP at minimum 5 viewpoints."}, {"id": "c_07", "type": "check", "order": 7, "title": "Dust & Debris Protection", "required": true, "description": "Avoid flying over active concrete cutting, grinding, or demolition. Dust infiltration can damage sensors and motors."}]', '1.5', true, false, NULL, '2026-03-27 19:46:40.243649-04', '2026-03-27 19:46:40.243649-04');
INSERT INTO public.protocols VALUES ('6922c17a-98c7-4e7d-a5d7-8831593f6fa5', NULL, 'Marketing & Media Assets Collection', 'Capture high-quality, cinematic shots for client marketing and internal portfolio use.', 'general', 'all', '[{"id": "mkt1", "type": "photo", "order": 1, "title": "Establishing Shot (Wide)", "required": true, "description": "Capture a wide-angle, high-altitude photo showing the entire site context."}, {"id": "mkt2", "type": "check", "order": 2, "title": "Cinematic Orbit (Video)", "required": true, "description": "Record a smooth 360-degree orbit around the primary structure at 4K 60fps."}, {"id": "mkt3", "type": "photo", "order": 3, "title": "Low-Angle Hero Shot", "required": true, "description": "Capture a dramatic, low-angle photo of the infrastructure against the skyline."}]', '1.0', true, false, NULL, '2026-05-04 22:12:40.381153-04', '2026-05-04 22:12:40.381153-04');
INSERT INTO public.protocols VALUES ('cbbf8c2a-f897-4129-8238-9b7b030c1b79', NULL, 'Volumetric Stockpile & Grade Monitoring Protocol', 'Protocol for accurate drone-based stockpile volume calculations and grading compliance checks on construction and mining sites.', 'mission', 'construction', '[{"id": "vol_01", "type": "check", "order": 1, "title": "Base Survey Confirmation", "required": true, "description": "Confirm availability of base survey / design grade file (.dxf, .dwg, or LandXML) for volume comparison. Obtain from site engineer before flight."}, {"id": "vol_02", "type": "check", "order": 2, "title": "GCP Placement", "required": true, "description": "Place minimum 5 GCPs around stockpile or grading area. GCPs must be surveyed by licensed surveyor to project datum. Minimum 3 per stockpile for independent check."}, {"id": "vol_03", "type": "check", "order": 3, "title": "Overlap Settings for Photogrammetry", "required": true, "description": "Set minimum 85% frontal overlap, 70% side overlap for stockpile model accuracy. Reduce flight speed for steep slopes (risk of motion blur)."}, {"id": "vol_04", "type": "check", "order": 4, "title": "Stockpile Safety Setback", "required": true, "description": "Maintain minimum 15 ft horizontal setback from pile edge during flight. Unstable stockpiles can shift suddenly — do not fly directly over peak."}, {"id": "vol_05", "type": "input", "order": 5, "title": "GPS Accuracy Log", "required": true, "description": "Note GPS accuracy indicator at mission start and end. For survey-grade deliverables, accept only if horizontal accuracy ≤ 5 cm with GCP correction."}, {"id": "vol_06", "type": "input", "order": 6, "title": "Material Identification", "required": false, "description": "Note stockpile material type (aggregate, topsoil, lumber, concrete rubble) — material type affects density conversion for mass calculations."}]', '1.2', true, false, NULL, '2026-03-27 19:46:40.245484-04', '2026-03-27 19:46:40.245484-04');
INSERT INTO public.protocols VALUES ('6e3c6fe2-7af3-4807-b75a-55654dfe8214', NULL, 'Urban / Congested Area Operations Protocol', 'Supplemental protocol for drone operations in urban environments, near populated areas, or above moving vehicles. Addresses advanced risk mitigation.', 'mission', 'all', '[{"id": "uca_01", "type": "check", "order": 1, "title": "Crowd Density Assessment", "required": true, "description": "Assess number of persons below intended flight path. Part 107 prohibits flight over moving vehicles or crowds without waiver. Document crowd conditions."}, {"id": "uca_02", "type": "check", "order": 2, "title": "Propeller Guard Evaluation", "required": false, "description": "Consider propeller guard use for close-proximity urban operations. Guards reduce injury potential but affect flight performance — confirm appropriate config."}, {"id": "uca_03", "type": "check", "order": 3, "title": "RF Congestion Check", "required": true, "description": "In dense urban areas, test RC signal strength at planned operating distance. If signal degraded > -85 dBm, reposition ground station or reduce operating distance."}, {"id": "uca_04", "type": "check", "order": 4, "title": "Bystander Barrier Setup", "required": false, "description": "Establish visible ground barriers or cones to discourage bystander approach. Post a ground crew member as crowd manager if bystanders are present."}, {"id": "uca_05", "type": "check", "order": 5, "title": "Visual Line of Sight Maintenance", "required": true, "description": "Confirm VLOS at all times without relay. In urban canyons, plan flight paths that maintain clear sightlines to aircraft at all mission points."}, {"id": "uca_06", "type": "input", "order": 6, "title": "Local Ordinance Compliance", "required": true, "description": "Check applicable city or county drone ordinances (many cities have local rules stricter than Part 107). Document compliance or exemptions."}]', '1.4', true, false, NULL, '2026-03-27 19:46:40.246721-04', '2026-03-27 19:46:40.246721-04');
INSERT INTO public.protocols VALUES ('ab846772-9696-41c1-b5fe-0220b13dd737', NULL, 'Night Operations Protocol', 'FAA Part 107 waiver or exception for nighttime drone operations. Required when flying between civil twilight and sunrise, or sunset and civil twilight.', 'mission', 'all', '[{"id": "ngt_01", "type": "check", "order": 1, "title": "Night Waiver / Exception", "required": true, "description": "Confirm FAA nighttime exception or waiver is active for this operation. Night flight allowed under Part 107 with anti-collision lighting visible at 3 statute miles."}, {"id": "ngt_02", "type": "check", "order": 2, "title": "Anti-Collision Lighting Verification", "required": true, "description": "Test all aircraft anti-collision lights (strobe + nav). Minimum flash rate 40 fpm. Visible at 3 statute miles. Have backup lights ready."}, {"id": "ngt_03", "type": "check", "order": 3, "title": "Site Lighting Assessment", "required": true, "description": "Survey site lighting conditions. Identify dark zones where VLOS may be lost. Plan mission route to maintain aircraft visibility at all points."}, {"id": "ngt_04", "type": "check", "order": 4, "title": "Night Vision & Crew Readiness", "required": true, "description": "Allow 20 minutes dark adaptation before night operations. Crew should not transition from bright-lit areas immediately before flight. No phone screens without red filter."}, {"id": "ngt_05", "type": "check", "order": 5, "title": "Enhanced Emergency Procedures", "required": true, "description": "Night emergency landing zones must be pre-surveyed in daylight. Mark landing zone with visible light markers. Confirm flashlight is available for each crew member."}, {"id": "ngt_06", "type": "sign", "order": 6, "title": "Pilot Night Currency", "required": true, "description": "Confirm pilot has completed recent night operations (within 90 days or per company policy). Night operations are higher risk — document pilot readiness."}]', '1.1', true, false, NULL, '2026-03-27 19:46:40.247823-04', '2026-03-27 19:46:40.247823-04');
INSERT INTO public.protocols VALUES ('6f4c2dee-e19c-46bb-a88f-2f670cdea550', NULL, 'Photogrammetry & Mapping Mission Protocol', 'Standardized procedure for drone mapping and photogrammetry deliverables. Ensures adequate overlap, GCP placement, and data quality for survey-grade outputs.', 'mission', 'all', '[{"id": "pm_01", "type": "input", "order": 1, "title": "Client Accuracy Requirements", "required": true, "description": "Confirm required horizontal and vertical accuracy from client specification. Survey grade (≤5 cm) requires GCPs. Mapping grade (10-20 cm) may use RTK only."}, {"id": "pm_02", "type": "check", "order": 2, "title": "Overlap Planning", "required": true, "description": "Set minimum 75% frontal, 65% side overlap for standard mapping. For complex terrain or dense vegetation, increase to 85%/75%."}, {"id": "pm_03", "type": "check", "order": 3, "title": "GCP Distribution", "required": false, "description": "Minimum 5 GCPs: 4 corners and 1 center. GCPs must be visible in imagery — use 60cm checkered targets. Additional GCPs for large AOI (1 per 50 acres)."}, {"id": "pm_04", "type": "input", "order": 4, "title": "GSD Verification", "required": true, "description": "Confirm Ground Sample Distance meets deliverable requirement. Typical: 2-5 cm/pixel. At 120m AGL with 20MP sensor, typical GSD ≈ 3 cm. Adjust altitude as needed."}, {"id": "pm_05", "type": "check", "order": 5, "title": "Sun Angle Optimization", "required": false, "description": "Avoid mapping within 1 hour of sunrise/sunset (long shadows reduce photogrammetry quality). Overcast lighting preferred — eliminates harsh shadows in canopy."}, {"id": "pm_06", "type": "check", "order": 6, "title": "Data Completeness Field Check", "required": true, "description": "After mission, confirm all planned flight lines flown. Check GCS for any aborted lines. Re-fly any gaps before leaving site."}]', '2.3', true, false, NULL, '2026-03-27 19:46:40.248846-04', '2026-03-27 19:46:40.248846-04');
INSERT INTO public.protocols VALUES ('efac54f1-6ba3-4531-a130-d041692c982c', NULL, 'Data Upload & Client Delivery Protocol', 'Standardized procedure for uploading, processing, and delivering drone data to clients. Ensures data integrity and chain of custody.', 'post_flight', 'all', '[{"id": "dup_01", "type": "check", "order": 1, "title": "Raw Data Backup", "required": true, "description": "Before any processing: create second backup copy of all raw data to separate drive or cloud storage. Verify file integrity with checksum if required."}, {"id": "dup_02", "type": "input", "order": 2, "title": "Platform Upload", "required": true, "description": "Upload data to processing platform (DroneDeploy, Pix4D, Propeller, ESRI, etc.) or to client-specified cloud storage. Note upload timestamp and confirmation."}, {"id": "dup_03", "type": "check", "order": 3, "title": "Processing Settings", "required": false, "description": "Confirm processing settings match deliverable specification: coordinate system, output resolution, GCP tie points, processing quality setting."}, {"id": "dup_04", "type": "check", "order": 4, "title": "Quality Check on Deliverable", "required": true, "description": "Before client delivery: verify map alignment with known landmarks, check orthophoto seam lines, confirm elevation data is within spec. Document QC findings."}, {"id": "dup_05", "type": "sign", "order": 5, "title": "Client Delivery Confirmation", "required": true, "description": "Send deliverables with delivery confirmation request. Include: flight date, equipment used, number of images, coverage area, and GSD or accuracy achieved."}, {"id": "dup_06", "type": "input", "order": 6, "title": "Data Retention Log", "required": false, "description": "Log delivery date, recipient, data format delivered, and retention period per agreement. Update project management system with completion status."}]', '1.3', true, false, NULL, '2026-03-27 19:46:40.251517-04', '2026-03-27 19:46:40.251517-04');
INSERT INTO public.protocols VALUES ('f1cc7ce6-e1c4-4423-99fe-e6793937ebbd', NULL, 'Aircraft Maintenance & Inspection Log Protocol', 'Post-mission aircraft maintenance documentation to track wear, maintenance intervals, and airworthiness over the fleet lifecycle.', 'post_flight', 'all', '[{"id": "maint_01", "type": "input", "order": 1, "title": "Propeller Condition Assessment", "required": true, "description": "Rate each propeller blade (1-5 scale): 1=New, 3=Visible wear acceptable, 5=Replace immediately. Log rating in aircraft maintenance record."}, {"id": "maint_02", "type": "check", "order": 2, "title": "Motor Bearing Check", "required": true, "description": "Spin each motor by hand after cooling. Note any grinding, clicking, or resistance. Motors > 200 flight hours or with abnormal sound should be inspected by tech."}, {"id": "maint_03", "type": "input", "order": 3, "title": "Total Flight Time Log", "required": true, "description": "Record total flight time for this session. Update aircraft logbook with cumulative flight hours. Flag aircraft for maintenance inspection per schedule (typically every 200 hrs)."}, {"id": "maint_04", "type": "input", "order": 4, "title": "Battery Cycle Count Update", "required": true, "description": "Update battery cycle count in battery management system. Flag any battery > 200 cycles for capacity test. Retire batteries that fail < 80% original capacity."}, {"id": "maint_05", "type": "check", "order": 5, "title": "Sensor Cleaning", "required": false, "description": "Clean all lens surfaces with appropriate optical cleaning kit. Remove debris from sensor vents. Check gimbal joints for debris or wear. Document any sensor damage."}]', '1.0', true, false, NULL, '2026-03-27 19:46:40.253408-04', '2026-03-27 19:46:40.253408-04');
INSERT INTO public.protocols VALUES ('4a44268c-6b19-4fa0-9af9-64a3a1129206', NULL, 'Severe Weather Abort Protocol', 'Decision criteria and required actions when weather conditions deteriorate unexpectedly during operations.', 'emergency', 'all', '[{"id": "swa_01", "type": "check", "order": 1, "title": "Immediate Abort Triggers", "required": true, "description": "Abort immediately if: sustained winds exceed 25 mph, lightning visible within 10 miles, precipitation begins, visibility drops below 3 SM, or unexpected fog rolls in."}, {"id": "swa_02", "type": "check", "order": 2, "title": "Rapid RTH Execution", "required": true, "description": "Initiate RTH or manual return. Set maximum allowable return speed. Do not attempt to complete mission objectives — land safely first."}, {"id": "swa_03", "type": "check", "order": 3, "title": "Equipment Protection", "required": true, "description": "If aircraft is safely landed: immediately cover sensors with lens caps, disconnect batteries, place equipment in protective cases. Do not handle electronics in lightning storm."}, {"id": "swa_04", "type": "check", "order": 4, "title": "Personnel Shelter", "required": true, "description": "Direct all crew to appropriate shelter — vehicle or substantial structure. Avoid lone trees, open fields, or elevated areas during lightning threat."}, {"id": "swa_05", "type": "input", "order": 5, "title": "Weather Hold Documentation", "required": true, "description": "Document time of abort, weather conditions observed, and equipment status. Notify client or operations center of weather hold. Note rescheduling window."}]', '1.1', true, false, NULL, '2026-03-27 19:46:40.254833-04', '2026-03-27 19:46:40.254833-04');
INSERT INTO public.protocols VALUES ('e0f0b206-c84a-4119-95a4-7dc4e8d76c5e', NULL, 'Property Contact & Incident Response Protocol', 'Immediate response procedures when aircraft makes unintended contact with a structure, vehicle, or ground obstacle.', 'emergency', 'all', '[{"id": "pci_01", "type": "check", "order": 1, "title": "Ensure Scene Safety", "required": true, "description": "First priority: confirm no persons are injured. Secure the immediate area. If LiPo battery is damaged/smoking — establish 30 ft exclusion zone and treat as fire hazard."}, {"id": "pci_02", "type": "check", "order": 2, "title": "Preserve Scene", "required": true, "description": "Do not move aircraft or damaged property until documentation is complete. Photograph the scene from multiple angles before any cleanup."}, {"id": "pci_03", "type": "sign", "order": 3, "title": "Property Owner Notification", "required": true, "description": "Identify and notify property owner if property was damaged. Exchange contact information. Do not make admissions of liability. Contact company legal/insurance."}, {"id": "pci_04", "type": "check", "order": 4, "title": "FAA Reportability Assessment", "required": true, "description": "Assess if incident meets FAA reporting threshold: property damage > $500 or serious injury. If yes, company must report within 10 days per §107.9."}, {"id": "pci_05", "type": "input", "order": 5, "title": "Incident Documentation", "required": true, "description": "Complete full incident report: time, location, weather conditions, mission phase, sequence of events, property/persons involved, and photos of damage."}, {"id": "pci_06", "type": "check", "order": 6, "title": "Aircraft Quarantine", "required": true, "description": "Remove aircraft from service until maintenance inspection is completed. Label aircraft \"Grounded - Incident Review.\" Do not fly until cleared by maintenance."}]', '1.0', true, false, NULL, '2026-03-27 19:46:40.256287-04', '2026-03-27 19:46:40.256287-04');
INSERT INTO public.protocols VALUES ('9535dad8-b264-45f7-a6f4-e543184664e9', NULL, 'Daily Equipment Readiness Inspection', 'Morning equipment inspection protocol for field teams. Ensures all aircraft, batteries, sensors, and support equipment are mission-ready before departing for the field.', 'general', 'all', '[{"id": "der_01", "type": "check", "order": 1, "title": "Aircraft Inventory", "required": true, "description": "Confirm all aircraft are accounted for, logged out, and assigned to pilots. Verify tail numbers match equipment tracking system."}, {"id": "der_02", "type": "check", "order": 2, "title": "Battery Charge Status", "required": true, "description": "All flight batteries should be charged to 90-100% for departure. Check storage batteries are at 50-60%. Log any batteries below threshold."}, {"id": "der_03", "type": "check", "order": 3, "title": "Case & Transport Security", "required": true, "description": "All equipment secured in transport cases. Pelican/hard cases latched and locked. Fragile sensors in foam-padded compartments. No loose items in vehicle."}, {"id": "der_04", "type": "check", "order": 4, "title": "Documentation Kit", "required": true, "description": "Pilot carries: current Remote Pilot Certificate, government ID, aircraft registration, insurance certificate, and any site-specific permits or authorization letters."}, {"id": "der_05", "type": "check", "order": 5, "title": "Safety Equipment", "required": true, "description": "First aid kit is present and fully stocked. Fire extinguisher or LiPo safety bag in vehicle. High-vis vest and hard hats available for all crew members."}, {"id": "der_06", "type": "check", "order": 6, "title": "Communications Check", "required": false, "description": "Cell phones fully charged. Radios paired and tested (for multi-crew operations). Emergency contacts saved. Operations center notified of mission schedule."}]', '1.1', true, false, NULL, '2026-03-27 19:46:40.257838-04', '2026-03-27 19:46:40.257838-04');
INSERT INTO public.protocols VALUES ('95823863-fdaa-4baa-ab32-e7d1ef070767', NULL, 'Client Site Access & Coordination Protocol', 'Standardized client and site coordination checklist completed before mission deployment. Ensures all parties are aligned on scope, access, and safety.', 'general', 'all', '[{"id": "csa_01", "type": "check", "order": 1, "title": "Access Credentials Confirmed", "required": true, "description": "Confirm gate codes, badge access, escort requirements, and check-in location with site contact. Test any access credentials before mission day."}, {"id": "csa_02", "type": "input", "order": 2, "title": "Scope of Work Agreement", "required": true, "description": "Confirm exact scope with client: areas to be flown, deliverable format, deadline, and any special requirements. Document any scope changes from original work order."}, {"id": "csa_03", "type": "check", "order": 3, "title": "Site Safety Plan Review", "required": false, "description": "Obtain and review client site safety plan or OSHA 300 log if applicable. Identify site-specific hazards not covered by standard protocols."}, {"id": "csa_04", "type": "check", "order": 4, "title": "Adjacent Airspace Notification", "required": false, "description": "If near airport/helipad: confirm notification to facility manager. Check for any local TFRs or temporary closures not yet in NOTAMs."}, {"id": "csa_05", "type": "input", "order": 5, "title": "Client Contact On-Site", "required": true, "description": "Confirm site contact will be available on mission day to address access issues. Obtain backup contact number. Agree on communication method (call vs. email vs. text)."}]', '1.0', true, false, NULL, '2026-03-27 19:46:40.260074-04', '2026-03-27 19:46:40.260074-04');
INSERT INTO public.protocols VALUES ('1d586fa1-a30e-479c-ad78-b969929fe07d', NULL, 'FAA Regulatory Compliance Verification', 'Annual regulatory review protocol ensuring all company operations remain compliant with FAA Part 107, company operations manual, and any applicable waivers.', 'general', 'all', '[{"id": "faa_01", "type": "check", "order": 1, "title": "Pilot Certificate Currency", "required": true, "description": "Confirm all pilots have passed FAA Remote Pilot Knowledge Test within 24 months. Recurrent testing is required to maintain certificate currency."}, {"id": "faa_02", "type": "check", "order": 2, "title": "Aircraft Registration", "required": true, "description": "Confirm all aircraft > 0.55 lbs are registered with FAA. Registration must be renewed every 3 years. Drone must be labeled with registration number."}, {"id": "faa_03", "type": "check", "order": 3, "title": "Waiver Status Review", "required": false, "description": "Review all active Part 107 waivers (night, BVLOS, speed, altitude, etc.). Confirm expiration dates and geographic boundaries. Renew 60+ days before expiration."}, {"id": "faa_04", "type": "check", "order": 4, "title": "LAANC / Airspace Authorizations", "required": true, "description": "Confirm LAANC authorization process is current for all operations in controlled airspace. Verify DroneZone authorizations for Class B/C/D/E surface."}, {"id": "faa_05", "type": "check", "order": 5, "title": "Incident Report Compliance", "required": true, "description": "Confirm any reportable incidents within past 12 months have been reported to FAA within required timeframe. Review ASRS reports filed."}, {"id": "faa_06", "type": "sign", "order": 6, "title": "Operations Manual Currency", "required": true, "description": "Confirm Operations Manual has been reviewed and updated within 12 months. All pilots have acknowledged latest version in writing."}]', '1.0', true, false, NULL, '2026-03-27 19:46:40.261307-04', '2026-03-27 19:46:40.261307-04');
INSERT INTO public.protocols VALUES ('8e8c6aed-f0e0-4fee-b2b9-9aff23166159', NULL, 'FAA Part 107 Pre-Flight Safety Checklist', 'Mandatory pre-flight checks to ensure the UAS is safe for operation according to FAA guidelines.', 'pre_flight', 'all', '[{"id": "pf1", "type": "check", "order": 1, "title": "Check Weather/TFRs", "required": true, "description": "Verify current METAR/TAF and check for active Temporary Flight Restrictions (TFRs)."}, {"id": "pf2", "type": "check", "order": 2, "title": "Airframe Inspection", "required": true, "description": "Inspect propellers, motors, and chassis for cracks, stress marks, or loose components."}, {"id": "pf3", "type": "check", "order": 3, "title": "Battery Validation", "required": true, "description": "Ensure battery is 100% charged, seated firmly, and shows no signs of swelling."}, {"id": "pf4", "type": "check", "order": 4, "title": "Compass Calibration", "required": true, "description": "Perform compass calibration if prompted or if moving to a new geographic location."}, {"id": "pf5", "type": "check", "order": 5, "title": "SD Card Check", "required": true, "description": "Format SD card and verify sufficient space for the mission."}]', '1.0', true, true, NULL, '2026-05-04 22:10:53.336835-04', '2026-05-04 22:10:53.336835-04');
INSERT INTO public.protocols VALUES ('23fd7b8a-4d30-4cc4-a608-b4d40d9c59be', NULL, 'Solar Photovoltaic Thermal Inspection (IEC 62446-3)', 'Standard operating procedure for performing a thermographic inspection of a utility-scale solar farm.', 'mission', 'solar', '[{"id": "si1", "type": "input", "order": 1, "title": "Irradiance Verification", "required": true, "description": "Confirm irradiance is above 600 W/m² (ideally >800 W/m²) for accurate thermal capture."}, {"id": "si2", "type": "check", "order": 2, "title": "Camera Settings Setup", "required": true, "description": "Set thermal palette to Ironbow/White Hot, adjust emissivity to 0.85 (glass), and set gimbal angle between -60° and -90°."}, {"id": "si3", "type": "check", "order": 3, "title": "GSD Verification", "required": true, "description": "Verify altitude achieves a Ground Sample Distance (GSD) of at least 3-5 cm/px for RGB and thermal."}, {"id": "si4", "type": "photo", "order": 4, "title": "Test Photo", "required": false, "description": "Capture a test thermal image. Ensure the delta-T between a hotspot and healthy panel is visible."}]', '1.0', true, true, NULL, '2026-05-04 22:10:53.360971-04', '2026-05-04 22:10:53.360971-04');
INSERT INTO public.protocols VALUES ('fc0739b1-463f-42c1-b8f5-3988d225d608', NULL, 'On-Site Data Quality Assurance (QA)', 'Mandatory review of captured imagery to ensure focus, exposure, and coverage are sufficient before leaving the site.', 'post_flight', 'all', '[{"id": "qa1", "type": "check", "order": 1, "title": "Image Focus Verification", "required": true, "description": "Zoom to 100% on a random sample of 5 images on the controller screen. Ensure edges and text are sharp and not blurry."}, {"id": "qa2", "type": "check", "order": 2, "title": "Motion Blur Check", "required": true, "description": "Verify that shutter speed was fast enough to prevent motion blur during flight (especially on corners/turns)."}, {"id": "qa3", "type": "check", "order": 3, "title": "Exposure & Glare", "required": true, "description": "Review images for overexposure or excessive sun glare on solar panels/reflective surfaces."}, {"id": "qa4", "type": "check", "order": 4, "title": "Overlap Confirmation", "required": true, "description": "If flying a mapping grid, verify that the drone successfully captured images with proper front/side overlap without dropped frames."}]', '1.0', true, true, NULL, '2026-05-04 22:15:45.440544-04', '2026-05-04 22:15:45.440544-04');
